def metric(label):
    target='CatalanCore.Uniform.Decay.Optimization.'+label
    matches=[]
    for path in LOGS.glob(target.replace('.','_')+'-build*.json'):
        record=json.loads(path.read_text(encoding='utf-8-sig'))
        if record.get('target')==target and record.get('mode')=='build' and record.get('rc')==0:matches.append((path.stat().st_mtime,path,record))
    assert matches,label
    _,path,record=max(matches);log=Path(record['log']);text=log.read_text(encoding='utf8')
    assert 'Build completed successfully' in text
    cumulative=text.rsplit('cumulative profiling times:',1)[-1]
    times=re.findall(r'\btype checking ([0-9.]+)(ms|s)',cumulative)
    kernel=float(times[-1][0])/(1000 if times[-1][1]=='ms'else 1)if times else 0
    module=re.findall(r'Built '+re.escape(target)+r' \(([0-9.]+)(ms|s)\)',text)
    module=float(module[-1][0])/(1000 if module[-1][1]=='ms'else 1)if module else None
    return dict(target=target,kernel_seconds=kernel,module_wall_seconds=module,wrapper_wall_seconds=record['wrapper_wall_seconds'],lean_peak_working_set_bytes=max(map(int,record['lean_process_peak_working_sets_bytes'].values()),default=0),observer=record.get('observer','legacy-PPID-observer'),log=str(log),json=str(path))
