def tail_receipt(frame,variant):
    f=Field(getrow(frame),variant);R=max(sum(map(abs,v))for p in f.pieces+f.nu for v in p[:2]);moment=Q(0)
    for fac,ps in((f.b,f.pieces),(Q(1),f.nu)):
        for a,b,cs in ps:moment+=abs(fac)*sum((abs(v)/Q(k+1)for k,v in enumerate(cs)),Q(0))*max(sum(map(abs,a)),sum(map(abs,b)))
    Y=Q(8);lower=A((1-f.eps)*Y)*arb.pi()-2*A(moment)/A(Y)
    assert Y>=2*R and lower>A(f.targets['ray'])
    return dict(frame=frame,variant=variant,label='E directed tail arithmetic relative to the signed moment-tail inequality',Y=str(Y),support_radius_L1_upper=str(R),absolute_first_moment_upper=str(moment),lower=str(-upper_q(-lower)),target=str(f.targets['ray']),passed=True)
