        endpoints=sum(n for k,v in cover['counts'].items()for rule,n in v['rules'].items()if rule.startswith('endpoint'));cells=cover['total_cells'];cell=metrics[prefix+'Data']['kernel_seconds']+metrics[prefix+'Stream']['kernel_seconds'];mom=metrics[momlabel]['kernel_seconds'];source_moment=json.loads((EVID/(momlabel+'-model.json')).read_text())
