        for key in('rational','log2'):
            assert row['Lambda'].get(key)==ref['Lambda'].get(key),(frame,key)
        g=groups[group];cand=json.loads((EVID/f'compact-{group}-{g["variant"]}.json').read_text());values=[row['gamma']*cand['numerical'][k]['c']/(cand['numerical'][k]['D']-row['Lambda']['upper'])for k in('fine','indep')]
