    audit=Path(metrics['FinalAudit']['log']).read_text(encoding='utf8');assert 'sorryAx'not in audit and 'Build completed successfully'in audit
    result=dict(status='DECAY_PERFORMANCE_LANE_NUMERIC_AND_KERNEL_COMPLETE',source_sha256=hashlib.sha256(SOURCE.read_bytes()).hexdigest(),groups=groups,per_constant=replays,measurements=metrics,measured_paired_indexed_closure_seconds=paired_indexed,measured_paired_streamed_closure_seconds=paired_stream,measured_far_compressed_closure_seconds=compressed,measured_shared_table_cell_closure_seconds=tables,measured_endpoint_closure_seconds=endpoint_cell,measured_once_table_seconds=metrics['Tables']['kernel_seconds'],tail_arithmetic=tails,energy_precision=json.loads((EVID/'energy-precision.json').read_text()),unmeasured=['Generic polynomial/log/arctan/multipole moment interpretation and soundness proofs','Full source/HasDecay assembly and final irrationality measure banking','Further production variation in coefficient sizes, endpoint neighborhoods and energygeometry'],proof_scope='Exact streaming-checker equality and coherent sharedtable arithmetic; closed actual numeric workloads and normalized moment trees. No HasDecay, new bound, or narrowing of signeddegree4/generalgeometry theorem domain.')
